const fs = require('fs');
const path = require('path');

/**
 * Loads every tour JSON generated by `npm run import:live` (one file per tour).
 * Signature journeys first (in the order of the live site), then cheapest first.
 */
const SIGNATURE_ORDER = [
  '8-day-great-migration-moments',
  '9-day-get-to-know-tanzania',
  '6-day-tanzania-beyond-experience',
  '7-day-february-calving-season-safari',
  '5-day-ndutu-calving-season-ngorongoro-crater-safari',
];

const rank = (t) => {
  const i = SIGNATURE_ORDER.indexOf(t.slug);
  return i === -1 ? 100 : i;
};

const tours = fs
  .readdirSync(__dirname)
  .filter((f) => f.endsWith('.json'))
  .map((f) => JSON.parse(fs.readFileSync(path.join(__dirname, f), 'utf8')))
  .sort((a, b) => rank(a) - rank(b) || a.priceFrom - b.priceFrom);

module.exports = tours.map((t, i) => ({ ...t, sort: i }));
